// Hub coordination index — record JAH-GPCS-SMARTHUB-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"protocols": 4, "device_limit": 200, "price_usd": 100};
var value = (m.protocols*m.device_limit/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-SMARTHUB-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-SMARTHUB-000001|' + value.toFixed(2) + ' coordination index');

